void act(int n) {
  Serial.print(n); Serial.println(n == 1 ? " clap: green" : (n == 2 ? " claps: red" : " claps: both"));
  digitalWrite(GREEN_LED, n == 1 || n >= 3);
  digitalWrite(RED_LED, n == 2 || n >= 3);
