int dryVal = 1023, wetVal = 0;
int step = 0;             // 0 = measuring with saved values, 1 = waiting for dry, 2 = waiting for wet

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(RED_LED, OUTPUT); pinMode(YELLOW_LED, OUTPUT); pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
  int d = EEPROM.read(0) * 256 + EEPROM.read(1);
  int w = EEPROM.read(2) * 256 + EEPROM.read(3);
  if (d > w && d <= 1023) { dryVal = d; wetVal = w; Serial.println("Loaded saved calibration"); }
  Serial.println("Button: start calibration (dry reading, then wet reading)");
}

void loop() {
  if (pressed()) {
    int v = analogRead(SOIL_PIN);
    if (step == 0) { step = 1; Serial.println("Hold the probe DRY and press the button"); }
    else if (step == 1) { dryVal = v; step = 2; Serial.print("dry = "); Serial.println(dryVal); Serial.println("Now WET and press the button"); }
    else { wetVal = v; step = 0;
      EEPROM.write(0, dryVal / 256); EEPROM.write(1, dryVal % 256); EEPROM.write(2, wetVal / 256); EEPROM.write(3, wetVal % 256);
      Serial.print("wet = "); Serial.println(wetVal); Serial.println("Calibration saved"); }
  }
  digitalWrite(RED_LED, step == 1);
  digitalWrite(YELLOW_LED, step == 2);
  digitalWrite(GREEN_LED, step == 0);
  if (step == 0 && millis() % 1000 < 20) {
    int pct = constrain(map(analogRead(SOIL_PIN), dryVal, wetVal, 0, 100), 0, 100);
    Serial.print("calibrated moisture "); Serial.print(pct); Serial.println(" %");
    delay(25);
  }
}

// ---- Circuit (Kit 2) ----
// Green LED anode -> 220 ohm -> D5, cathode -> GND
// Red LED anode -> 220 ohm -> D3, cathode -> GND
// 10k pot: ends to 5V and GND, wiper -> A0
// NTC 10k thermistor + 10k resistor divider (5V - NTC - A1 - 10k - GND)
#define GREEN_LED 5
#define RED_LED 3
#define POT A0
#define NTC_PIN A1

float ntcC() {                        // NTC on the 5V side, 10k resistor to GND
  int adc = analogRead(NTC_PIN);
  if (adc < 1) adc = 1;
  float r = 10000.0 * (1023.0 / adc - 1.0);
  float k = 1.0 / (1.0 / 298.15 + log(r / 10000.0) / 3950.0);   // beta equation, B = 3950
  return k - 273.15;
}

bool fanOn = false;

void setup() {
  pinMode(GREEN_LED, OUTPUT); pinMode(RED_LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  float limit = 20.0 + analogRead(POT) * 20.0 / 1023.0;
  float t = ntcC();
  if (!fanOn && t > limit + 1.0) fanOn = true;
  if (fanOn && t < limit - 1.0) fanOn = false;
  digitalWrite(GREEN_LED, fanOn);
  digitalWrite(RED_LED, !fanOn);
  Serial.print("temp "); Serial.print(t, 1); Serial.print(" C  target "); Serial.print(limit, 1);
  Serial.println(fanOn ? " C  FAN ON" : " C  fan off");
  delay(500);
}

