int fault = 0;           // 0 ok, 1 frost, 2 overheat, 3 sensor disagreement (latched until acknowledged)
unsigned long lastPrint = 0;

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(RED_LED, OUTPUT); pinMode(GREEN_LED, OUTPUT); pinMode(BUZZER, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  float a = lm35C(), b = ntcC();
  float t = (a + b) / 2.0;
  if (fault == 0) {
    if (t < 3.0) fault = 1;
    else if (t > 40.0) fault = 2;
    else if (abs(a - b) > 6.0) fault = 3;
    if (fault) { Serial.print("FAULT "); Serial.println(fault == 1 ? "frost" : (fault == 2 ? "overheat" : "sensor mismatch")); }
  }
  if (pressed()) {
    if (t >= 5.0 && t <= 38.0 && abs(a - b) <= 6.0) { fault = 0; Serial.println("fault acknowledged"); }
    else Serial.println("cannot acknowledge: still out of range");
  }
  digitalWrite(GREEN_LED, fault == 0);
  digitalWrite(RED_LED, fault != 0);
  digitalWrite(BUZZER, fault != 0 && (millis() / 300) % 2);
  if (millis() - lastPrint > 1000) { lastPrint = millis(); Serial.print("LM35 "); Serial.print(a, 1); Serial.print("  NTC "); Serial.println(b, 1); }
}

