void setup() {
  pinMode(RED_LED, OUTPUT); pinMode(GREEN_LED, OUTPUT); pinMode(YELLOW_LED, OUTPUT); pinMode(BLUE_LED, OUTPUT); pinMode(BUZZER, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int sens = map(analogRead(POT), 0, 1023, 300, 800);      // lower = more sensitive
  int v = analogRead(SND_PIN);
  int level = 0;
  if (v > sens * 0.5) level = 1;
  if (v > sens * 0.7) level = 2;
  if (v > sens * 0.9) level = 3;
  if (v > sens * 1.1) level = 4;
  digitalWrite(BLUE_LED, level >= 1);
  digitalWrite(GREEN_LED, level >= 2);
  digitalWrite(YELLOW_LED, level >= 3);
  digitalWrite(RED_LED, level >= 4);
  if (level == 4 && millis() - lastBeat > 300) { lastBeat = millis(); digitalWrite(BUZZER, HIGH); delay(40); digitalWrite(BUZZER, LOW); }
  Serial.print("sound "); Serial.print(v); Serial.print("  sensitivity "); Serial.print(sens); Serial.print("  level "); Serial.println(level);
  delay(60);
}

