float lastT = -99;
unsigned long lastChange = 0;
int code = 0;
unsigned long lastCheck = 0;

void blinkCode(int n) {
  for (int i = 0; i < n; i++) { digitalWrite(RED_LED, HIGH); delay(200); digitalWrite(RED_LED, LOW); delay(250); }
  delay(700);
}

void setup() {
  pinMode(RED_LED, OUTPUT); pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
  dht.begin();
  lastChange = millis();
}

void loop() {
  if (millis() - lastCheck >= 1000) {
    lastCheck = millis();
    code = 0;
    if (isnan(dht.readTemperature()) || isnan(dht.readHumidity())) code = 1;
    float t = lm35C();
    if (t < -5 || t > 140) code = 2;
    if (t != lastT) { lastT = t; lastChange = millis(); }
    int soil = analogRead(SOIL_PIN);
    if (soil > 1018 || soil < 3) code = 3;                 // reading pinned at a rail: probe unplugged or shorted
    Serial.print("health code "); Serial.println(code);
  }
  digitalWrite(GREEN_LED, code == 0);
  if (code != 0) blinkCode(code);
}

