// Green LED anode -> 220 ohm -> D5, cathode -> GND
// Red LED anode -> 220 ohm -> D3, cathode -> GND
// LDR module: VCC 5V, GND, AO -> A0 (bright = low reading)
// Sound sensor: VCC 5V, GND, AO -> A1
#define GREEN_LED 5
#define RED_LED 3
#define LDR_PIN A0
#define SND_PIN A1

float score = 0;
int lastLight = 0;
unsigned long lastTick = 0, lastPrint = 0;
