#include <DHT.h>
DHT dht(DHT_PIN, DHT11);
float lm35C() {                       // 10 mV per degree C, 5 V reference, 10-bit ADC
  return analogRead(LM35_PIN) * 500.0 / 1023.0;
}

float temp[24], hum[24];
int dark[24];
int hour = 0;
unsigned long last = 0;

void report() {
  float tMin = 999, tMax = -999, tSum = 0, hSum = 0;
  int dMax = 0;
  Serial.println();
  Serial.println("=========== DAILY CLIMATE REPORT ===========");
  Serial.println("hour | temp C | RH % | darkness");
  for (int i = 0; i < 24; i++) {
    Serial.print(i); Serial.print("    | "); Serial.print(temp[i], 1); Serial.print("   | "); Serial.print(hum[i], 0); Serial.print("   | "); Serial.println(dark[i]);
    if (temp[i] < tMin) tMin = temp[i];
    if (temp[i] > tMax) tMax = temp[i];
    tSum += temp[i]; hSum += hum[i];
    if (dark[i] > dMax) dMax = dark[i];
  }
  Serial.print("Temperature: min "); Serial.print(tMin, 1); Serial.print("  max "); Serial.print(tMax, 1); Serial.print("  avg "); Serial.println(tSum / 24, 1);
  Serial.print("Humidity avg "); Serial.print(hSum / 24, 0); Serial.print(" %   darkest reading "); Serial.println(dMax);
  Serial.println("============================================");
}

void setup() {
  Serial.begin(9600);
  dht.begin();
  Serial.println("Collecting 24 hourly samples (1 s = 1 hour)...");
}

void loop() {
  if (millis() - last >= 1000) {
    last = millis();
    temp[hour] = (dht.readTemperature() + lm35C()) / 2.0;
    hum[hour] = dht.readHumidity();
    dark[hour] = analogRead(LDR_PIN);
    hour++;
    if (hour == 24) { report(); hour = 0; }
  }
}

// ---- Circuit (Kit 2) ----
// DHT11: VCC 5V, GND, DATA -> D8
// Red LED anode -> 220 ohm -> D3, cathode -> GND
// Green LED anode -> 220 ohm -> D5, cathode -> GND
// 10k pot: ends to 5V and GND, wiper -> A0
// Rain sensor: VCC 5V, GND, AO -> A1 (dry = high reading)
#define DHT_PIN 8
#define RED_LED 3
#define GREEN_LED 5
#define POT A0
#define RAIN_PIN A1

#include <DHT.h>
DHT dht(DHT_PIN, DHT11);
int wetPct() { return constrain(map(analogRead(RAIN_PIN), 1023, 0, 0, 100), 0, 100); }

bool on = false;
unsigned long changedAt = 0;
unsigned long lastPrint = 0;

void setup() {
  pinMode(GREEN_LED, OUTPUT); pinMode(RED_LED, OUTPUT);
  Serial.begin(9600);
  dht.begin();
  changedAt = millis() - 6000;
}

void loop() {
  float target = 40.0 + analogRead(POT) * 30.0 / 1023.0;      // 40 .. 70 %
  if (wetPct() > 20) target -= 8.0;                            // rain: aim lower, the air will be damp
  float h = dht.readHumidity();
  bool wantOn = on ? (h > target - 3.0) : (h > target + 3.0);  // 3 % hysteresis band
  bool canSwitch = millis() - changedAt > 5000;                // protect the compressor: 5 s minimum
  if (wantOn != on && canSwitch) {
    on = wantOn; changedAt = millis();
    Serial.println(on ? "dehumidifier ON" : "dehumidifier OFF");
  }
  digitalWrite(GREEN_LED, on);
  digitalWrite(RED_LED, wantOn != on);                        // waiting for the minimum time
  if (millis() - lastPrint > 1500) {
    lastPrint = millis();
    Serial.print("RH "); Serial.print(h, 0); Serial.print(" %  target "); Serial.print(target, 0); Serial.println(on ? " %  [ON]" : " %  [off]");
  }
}

// ---- Circuit (Kit 2) ----
// Active buzzer + -> D12, - -> GND
// Red LED anode -> 220 ohm -> D3, cathode -> GND
// Green LED anode -> 220 ohm -> D5, cathode -> GND
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
// 10k pot: ends to 5V and GND, wiper -> A0
// Soil moisture probe: VCC 5V, GND, AO -> A1 (dry = high reading)
#define BUZZER 12
#define RED_LED 3
#define GREEN_LED 5
#define BTN1 2
#define POT A0
#define SOIL_PIN A1

int soilPct() { return constrain(map(analogRead(SOIL_PIN), 1023, 0, 0, 100), 0, 100); }
int lastBtn = HIGH;
bool pressed() {
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}

float lastPct = -1;
float rate = 0;                    // percent lost per second (smoothed)
unsigned long last = 0, lastBeep = 0;

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(RED_LED, OUTPUT); pinMode(GREEN_LED, OUTPUT); pinMode(BUZZER, OUTPUT);
  Serial.begin(9600);
  Serial.println("Pot = critical level (10-50 %). Button = pretend I watered the plant.");
}

void loop() {
  int critical = map(analogRead(POT), 0, 1023, 10, 50);
  if (pressed()) { rate = 0; Serial.println("watered - drying history cleared"); }
  if (millis() - last >= 1000) {
    last = millis();
    float pct = soilPct();
    if (lastPct >= 0) rate = rate * 0.7 + (lastPct - pct) * 0.3;   // positive = drying
    lastPct = pct;
    float eta = -1;
    if (rate > 0.05 && pct > critical) eta = (pct - critical) / rate;
    bool early = (eta >= 0 && eta < 30) || pct <= critical;
    digitalWrite(GREEN_LED, !early);
    digitalWrite(RED_LED, early);
    if (early && millis() - lastBeep > 4000) { lastBeep = millis(); digitalWrite(BUZZER, HIGH); delay(150); digitalWrite(BUZZER, LOW); }
    Serial.print("moisture "); Serial.print(pct, 0); Serial.print(" %  drying "); Serial.print(rate, 2); Serial.print(" %/s  critical "); Serial.print(critical);
    if (pct <= critical) Serial.println(" %  CRITICAL NOW");
    else if (eta >= 0) { Serial.print(" %  critical in ~"); Serial.print(eta, 0); Serial.println(" s"); }
    else Serial.println(" %  stable");
  }
}
